/* بيانات باب hadithq: تُحمَّل عند أول فتح للقسم */
window.HADITHQ = {"ch":[{"id":"sunna","t":"السنة في القرآن الكريم","d":"آيات أمر الله فيها بطاعة رسوله ﷺ واتباعه والتحاكم إليه، وبيّن أن بيانه للوحي من مهمته، وأن ما نطق به وحي؛ يقترن بكل آية حديث ثابت في معناها ونقل من المفسرين في الاستدلال بها على حجية السنة."},{"id":"tafsir","t":"التفسير النبوي: آيات بيّنها النبي ﷺ","d":"آيات فسّرها النبي ﷺ بنفسه أو بيّن المراد منها لما سُئل عنها، فهي أصح التفسير وأولاه بالقبول. كل مادة: الآية، ثم لفظ الحديث بتخريجه، ثم بيان وجه الصلة، ثم قول المفسر."},{"id":"tala","t":"آيات تلاها النبي ﷺ أو قال فيها «اقرؤوا إن شئتم»","d":"أحاديث استشهد فيها النبي ﷺ أو راويه بآية، فقال «اقرؤوا إن شئتم» أو «ثم قرأ»، فجعل الآية تصديقاً لما أخبر به من أمر الآخرة أو الأخلاق والأحكام."},{"id":"fadl","t":"فضل آيات وسور بعينها","d":"أحاديث صحيحة سمّت آيات وسوراً من القرآن الكريم وذكرت فضلها. وهي هنا بنصها ولفظ الآية، وليس فيها ما يُعمل به من غير دليل؛ فالتفصيل في الرقية والأذكار يرد في بابيه «التداوي بالقرآن» و«أذكار الصباح والمساء»."},{"id":"asbab","t":"أحاديث ذكرت نزول آيات","d":"أحاديث صحيحة صرّح فيها الراوي بأن آية نزلت في حادثة بعينها أو أن النبي ﷺ قالها عند نزولها. وتفصيل علم أسباب النزول في باب «علوم القرآن»، وهنا ما صحّ فيه الحديث بلفظه."},{"id":"dua","t":"آيات عمل بها النبي ﷺ في دعائه وذكره","d":"أحاديث ذكر فيها دعاء النبي ﷺ أو عمله بمقتضى آية، فالآية فيها تُترجم عملاً."}],"e":[{"id":"t4_59","ch":"sunna","t":"طاعة الله والرسول ﷺ","ay":[[4,59]],"h":[{"b":"bukhari","n":"7137","x":"مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ، وَمَنْ أَطَاعَ أَمِيرِي فَقَدْ أَطَاعَنِي، وَمَنْ عَصَى أَمِيرِي فَقَدْ عَصَانِي","gr":"صحيح: رواه البخاري"}],"f":"قرن الله طاعة الرسول ﷺ بطاعته في الآية، وبيّن الحديث أن طاعة الرسول طاعة لله وأن معصيته معصية له.","en_h":"The Prophet ﷺ said: \"Whoever obeys me has obeyed Allah, and whoever disobeys me has disobeyed Allah; whoever obeys my commander has obeyed me, and whoever disobeys my commander has disobeyed me.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":4,"ay":59,"x":"﴿أَطِيعُوا اللَّهَ﴾ أَيْ: اتَّبِعُوا كِتَابَهُ ﴿وَأَطِيعُوا الرَّسُولَ﴾ أَيْ: خُذُوا بِسُنَّتِهِ ﴿وَأُولِي الأمْرِ مِنْكُمْ﴾ أَيْ: فِيمَا أَمَرُوكُمْ بِهِ مِنْ طَاعَةِ اللَّهِ لَا فِي مَعْصِيَةِ اللَّهِ","en":"\"Obey Allah\" means follow His Book, \"and obey the Messenger\" means hold to his Sunnah, \"and those in authority among you\" in what they command you of obedience to Allah, not in disobedience to Allah."}},{"id":"t4_80","ch":"sunna","t":"من يطع الرسول فقد أطاع الله","ay":[[4,80]],"h":[{"b":"bukhari","n":"7280","x":"كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ، إِلاَّ مَنْ أَبَى \". قَالُوا يَا رَسُولَ اللَّهِ وَمَنْ يَأْبَى قَالَ \" مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى","gr":"صحيح: رواه البخاري"}],"f":"الآية تقرر أن طاعة الرسول ﷺ طاعة لله، والحديث يجعل طاعته سبيل دخول الجنة وعصيانه إباءً لها.","en_h":"The Prophet ﷺ said: \"All my community will enter Paradise except those who refuse.\" They said: \"Who refuses, O Messenger of Allah?\" He said: \"Whoever obeys me enters Paradise, and whoever disobeys me has refused.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":4,"ay":80,"x":"يُخْبِرُ تَعَالَى عَنْ عَبْدِهِ وَرَسُولِهِ مُحَمَّدٍ ﷺ بِأَنَّهُ مَنْ أَطَاعَهُ فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَاهُ فَقَدْ عَصَى اللَّهَ، وَمَا ذَاكَ إِلَّا لِأَنَّهُ مَا يَنْطِقُ عَنِ الْهَوَى، إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى.","en":"Allah informs about His servant and Messenger Muhammad ﷺ that whoever obeys him has obeyed Allah and whoever disobeys him has disobeyed Allah, and that is only because he does not speak from desire; it is only revelation revealed."}},{"id":"t59_7","ch":"sunna","t":"وما آتاكم الرسول فخذوه","ay":[[59,7]],"h":[{"b":"bukhari","n":"4886","x":"لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُوتَشِمَاتِ وَالْمُتَنَمِّصَاتِ وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ. فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ بَنِي أَسَدٍ يُقَالُ لَهَا أُمُّ يَعْقُوبَ، فَجَاءَتْ فَقَالَتْ إِنَّهُ بَلَغَنِي أَنَّكَ لَعَنْتَ كَيْتَ وَكَيْتَ. فَقَالَ وَمَا لِي لاَ أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَمَنْ هُوَ فِي كِتَابِ اللَّهِ فَقَالَتْ لَقَدْ قَرَأْتُ مَا بَيْنَ اللَّوْحَيْنِ فَمَا وَجَدْتُ فِيهِ مَا تَقُولُ. قَالَ لَئِنْ كُنْتِ قَرَأْتِيهِ لَقَدْ وَجَدْتِيهِ، أَمَا قَرَأْتِ {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا}. قَالَتْ بَلَى. قَالَ فَإِنَّهُ قَدْ نَهَى عَنْهُ","gr":"صحيح: رواه البخاري"}],"f":"استدل ابن مسعود رضي الله عنه بالآية على أن ما نهى عنه الرسول ﷺ فهو منهي عنه في كتاب الله، لأن الآية أمرت بأخذ ما جاء به.","en_h":"Ibn Mas'ud said: \"Allah has cursed the women who tattoo and the one who has it done, those who pluck the eyebrows and those who file their teeth for beauty, changing the creation of Allah.\" A woman of Banu Asad, Umm Ya'qub, objected, so he said: \"Have you not read: What the Messenger gives you, take; and what he forbids you, abstain? She said yes. He said: Then he has forbidden it.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":59,"ay":7,"x":"وَقَوْلُهُ: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا﴾ أَيْ: مَهْمَا أَمَرَكُمْ بِهِ فَافْعَلُوهُ، وَمَهْمَا نَهَاكُمْ عَنْهُ فَاجْتَنِبُوهُ، فَإِنَّهُ إِنَّمَا يَأْمُرُ بِخَيْرٍ وَإِنَّمَا يَنْهَى عَنْ شَرٍّ.","en":"\"And what the Messenger gives you, take; and what he forbids you, abstain\" means: whatever he commands you, do it, and whatever he forbids you, avoid it, for he only commands good and only forbids evil."}},{"id":"t16_44","ch":"sunna","t":"لتبيّن للناس ما نُزّل إليهم","ay":[[16,44]],"h":[{"b":"abudawud","n":"4604","x":"أَلاَ إِنِّي أُوتِيتُ الْكِتَابَ وَمِثْلَهُ مَعَهُ أَلاَ يُوشِكُ رَجُلٌ شَبْعَانُ عَلَى أَرِيكَتِهِ يَقُولُ عَلَيْكُمْ بِهَذَا الْقُرْآنِ فَمَا وَجَدْتُمْ فِيهِ مِنْ حَلاَلٍ فَأَحِلُّوهُ وَمَا وَجَدْتُمْ فِيهِ مِنْ حَرَامٍ فَحَرِّمُوهُ","gr":"رواه أبو داود · الحكم في مصدر البيانات — الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح"}],"f":"بيّن الله أن مهمة الرسول ﷺ شرح ما نزل إليه، والحديث ينبّه إلى أن السنة وحي يُعمل به كما يُعمل بالقرآن، فلا يجوز الاكتفاء بالقرآن وحده.","en_h":"The Prophet ﷺ said: \"Beware! I have been given the Book and the like of it with it. Beware! A man sated on his couch may say: Keep to this Quran; what you find lawful in it, treat as lawful, and what you find forbidden in it, treat as forbidden.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":16,"ay":44,"x":"ثُمَّ قَالَ تَعَالَى: ﴿وَأَنزلْنَا إِلَيْكَ الذِّكْرَ﴾ يَعْنِي: الْقُرْآنَ، ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نزلَ إِلَيْهِمْ﴾ مِنْ رَبِّهِمْ، أَيْ: لِعِلْمِكَ بِمَعْنَى مَا أُنْزِلَ عَلَيْكَ، وَحِرْصِكَ عَلَيْهِ، وَاتِّبَاعِكَ لَهُ، وَلِعِلْمِنَا بِأَنَّكَ أَفْضَلُ الْخَلَائِقِ وَسَيِّدُ وَلَدِ آدَمَ، فَتُفَصِّلَ لَهُمْ مَا أُجْمِلَ، وَتُبَيِّنَ لَهُمْ مَا أُشْكِلَ: ﴿وَلَعَلَّهُمْ يَتَفَكَّرُونَ﴾ أَيْ: يَنْظُرُونَ لِأَنْفُسِهِمْ فَيَهْتَدُونَ، فَيَفُوزُونَ بِالنَّجَاةِ فِي الدارين.","en":"Then Allah said: \"And We sent down to you the Reminder\", meaning the Quran, \"that you may make clear to the people what was sent down to them\" from their Lord, that is, because of your knowledge of the meaning of what was sent down to you, your keenness on it and your following of it, and because We know that you are the best of creation and the master of the children of Adam, so you may detail for them what was general and clarify for them what was obscure: \"and that they might reflect\", that is, look to themselves and be guided and attain salvation in both abodes."}},{"id":"t33_21","ch":"sunna","t":"لقد كان لكم في رسول الله أسوة حسنة","ay":[[33,21]],"h":[{"b":"bukhari","n":"631","x":"وَصَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي","gr":"صحيح: رواه البخاري"},{"b":"muslim","n":"1297","x":"لِتَأْخُذُوا مَنَاسِكَكُمْ فَإِنِّي لاَ أَدْرِي لَعَلِّي لاَ أَحُجُّ بَعْدَ حَجَّتِي هَذِهِ","gr":"صحيح: رواه مسلم"}],"f":"أمر الله بالتأسي بالنبي ﷺ، وفي الحديثين تطبيق ذلك: أن تُؤدّى العبادات كما رآها الناس منه، في الصلاة والحج.","en_h":"The Prophet ﷺ said: \"Pray as you have seen me pray.\" And at the Hajj he said, while casting pebbles on his mount: \"Take your rites from me, for I do not know whether I will perform Hajj again after this Hajj of mine.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":33,"ay":21,"x":"هَذِهِ الْآيَةُ الْكَرِيمَةُ أَصْلٌ كَبِيرٌ فِي التَّأَسِّي بِرَسُولِ اللَّهِ ﷺ فِي أَقْوَالِهِ وَأَفْعَالِهِ وَأَحْوَالِهِ","en":"This noble verse is a great principle in following the Messenger of Allah ﷺ in his words, deeds and states."}},{"id":"t4_65","ch":"sunna","t":"فلا وربك لا يؤمنون حتى يحكّموك","ay":[[4,65]],"h":[{"b":"bukhari","n":"2361","x":"يَا زُبَيْرُ اسْقِ ثُمَّ أَرْسِلْ \". فَقَالَ الأَنْصَارِيُّ إِنَّهُ ابْنُ عَمَّتِكَ. فَقَالَ عَلَيْهِ السَّلاَمُ \" اسْقِ يَا زُبَيْرُ، ثُمَّ يَبْلُغُ الْمَاءُ الْجَدْرَ، ثُمَّ أَمْسِكْ \". فَقَالَ الزُّبَيْرُ فَأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ {َلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ\"}","gr":"صحيح: رواه البخاري"}],"f":"روى الزبير أن الآية نزلت في خصومته مع رجل من الأنصار حكم فيها النبي ﷺ، فبيّنت أن الإيمان لا يتم إلا بالتسليم لحكمه ظاهراً وباطناً.","en_h":"Al-Zubayr said: \"The Prophet ﷺ said: O Zubayr, irrigate, then let the water go to your neighbour.\" And he said: \"I think this verse was revealed about that: No, by your Lord, they will not believe until they make you the judge in what is in dispute between them.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":4,"ay":65,"x":"يُقْسِمُ تَعَالَى بِنَفْسِهِ الْكَرِيمَةِ الْمُقَدَّسَةِ: أَنَّهُ لَا يُؤْمِنُ أَحَدٌ حَتَّى يُحَكم الرَّسُولَ ﷺ فِي جَمِيعِ الْأُمُورِ، فَمَا حَكَمَ بِهِ فَهُوَ الْحَقُّ الَّذِي يَجِبُ الِانْقِيَادُ لَهُ بَاطِنًا وَظَاهِرًا","en":"Allah swears by His noble, sanctified Self that no one believes until he makes the Messenger ﷺ judge in all matters; whatever he judges is the truth which must be submitted to, inwardly and outwardly."}},{"id":"t3_31","ch":"sunna","t":"إن كنتم تحبون الله فاتبعوني","ay":[[3,31]],"h":[{"b":"muslim","n":"1718","x":"مَنْ عَمِلَ عَمَلاً لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ","gr":"صحيح: رواه مسلم"}],"f":"جعلت الآية اتباع النبي ﷺ علامة محبة الله، والحديث يضع ميزان قبول العمل: أن يكون على أمره ﷺ.","en_h":"The Prophet ﷺ said: \"Whoever does a deed that is not in accordance with our command, it is rejected.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":3,"ay":31,"x":"هَذِهِ الْآيَةُ الْكَرِيمَةُ حَاكِمَةٌ عَلَى كُلِّ مَنِ ادَّعَى مَحَبَّةَ اللَّهِ، وَلَيْسَ هُوَ عَلَى الطَّرِيقَةِ الْمُحَمَّدِيَّةِ فَإِنَّهُ كَاذِبٌ فِي دَعْوَاهُ فِي نَفْسِ الْأَمْرِ، حَتَّى يَتَّبِعَ الشَّرْعَ الْمُحَمَّدِيَّ وَالدِّينَ النَّبَوِيَّ فِي جَمِيعِ أَقْوَالِهِ وَأَحْوَالِهِ، كَمَا ثَبَتَ فِي الصَّحِيحِ عَنْ رَسُولِ اللَّهِ ﷺ أَنَّهُ قَالَ: \"مَنْ عَمِلَ عَمَلا لَيْسَ عَلَيْهِ أمْرُنَا فَهُوَ رَدُّ","en":"This noble verse judges everyone who claims to love Allah while not following the Muhammadan way: he is lying in his claim in reality until he follows the Muhammadan law and the Prophetic religion in all his words and states, as it is established in the Sahih that the Messenger of Allah ﷺ said: \"Whoever does a deed that is not in accordance with our command, it is rejected.\""}},{"id":"t24_63","ch":"sunna","t":"فليحذر الذين يخالفون عن أمره","ay":[[24,63]],"h":[{"b":"bukhari","n":"5063","x":"فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي","gr":"صحيح: رواه البخاري"}],"f":"حذّرت الآية من مخالفة أمره ﷺ، وجاء الحديث في من رغب عن سنته ولو قصد العبادة، فبيّن أن الاقتداء به شرط.","en_h":"The Prophet ﷺ said: \"By Allah, I am the most fearful of Allah among you and the most mindful of Him, yet I fast and break the fast, pray and sleep and marry women; so whoever turns away from my Sunnah is not of me.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":24,"ay":63,"x":"وَقَوْلُهُ: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ﴾ أَيْ: عَنْ أَمْرَ رَسُولِ اللَّهِ ﷺ، سبيله هو وَمِنْهَاجُهُ وَطَرِيقَتُهُ [وَسُنَّتُهُ] وَشَرِيعَتُهُ، فَتُوزَنُ الْأَقْوَالُ وَالْأَعْمَالُ بِأَقْوَالِهِ وَأَعْمَالِهِ، فَمَا وَافَقَ ذَلِكَ قُبِل، وَمَا خَالَفَهُ فَهُوَ مَرْدُود عَلَى قَائِلِهِ وَفَاعِلِهِ، كَائِنًا مَا كَانَ، كَمَا ثَبَتَ فِي الصَّحِيحَيْنِ وَغَيْرِهِمَا، عَنْ رَسُولِ اللَّهِ ﷺ أَنَّهُ قَالَ: \"مَنْ عَمِلَ عَمَلا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدّ\" .","en":"\"Let those beware who oppose his command\" means the command of the Messenger of Allah ﷺ, his path, his method, his way [and his Sunnah] and his law; words and deeds are weighed against his words and deeds, so what agrees with them is accepted and what contradicts them is rejected against whoever said or did it, whoever he may be, as established in the two Sahihs and elsewhere from the Messenger of Allah ﷺ: \"Whoever does a deed that is not in accordance with our command, it is rejected.\""}},{"id":"t53_3","ch":"sunna","t":"وما ينطق عن الهوى","ay":[[53,3,4]],"h":[{"b":"abudawud","n":"3646","x":"اكْتُبْ فَوَالَّذِي نَفْسِي بِيَدِهِ مَا يَخْرُجُ مِنْهُ إِلاَّ حَقٌّ","gr":"رواه أبو داود · الحكم في مصدر البيانات — الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح"}],"f":"قرّرت الآية أن ما ينطق به النبي ﷺ وحي، وأكد الحديث أن كل ما يخرج منه حق، فلا يُردّ شيء من سنته الثابتة.","en_h":"Abdullah ibn Amr said he used to write down everything he heard from the Messenger of Allah ﷺ; Quraysh forbade him, saying he was a man who spoke in anger and in pleasure. So he told the Messenger of Allah ﷺ, who pointed to his mouth and said: \"Write, for by Him in whose hand is my soul, nothing comes out of it but the truth.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":53,"ay":3,"x":"﴿وَمَا يَنْطِقُ عَنِ الْهَوَى﴾ أَيْ: مَا يَقُولُ قَوْلًا عَنْ هَوًى وَغَرَضٍ، ﴿إِنْ هُوَ إِلا وَحْيٌ يُوحَى﴾ أَيْ: إِنَّمَا يَقُولُ مَا أُمِرَ بِهِ، يُبَلِّغُهُ إِلَى النَّاسِ كَامِلًا موفَّرًا مِنْ غَيْرِ زِيَادَةٍ وَلَا نُقْصَانٍ","en":"\"Nor does he speak from desire\" means he does not say anything out of whim or purpose; \"It is not but a revelation revealed\" means he only says what he was commanded, conveying it to people complete and whole, without addition or omission."}},{"id":"t6_82","ch":"tafsir","t":"الظلم المراد بالآية: الشرك","ay":[[6,82]],"h":[{"b":"bukhari","n":"3360","x":"لَيْسَ كَمَا تَقُولُونَ {لَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ} بِشِرْكٍ، أَوَلَمْ تَسْمَعُوا إِلَى قَوْلِ لُقْمَانَ لاِبْنِهِ {يَا بُنَىَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ}","gr":"صحيح: رواه البخاري"}],"f":"شقّ على الصحابة أن يُحمل «الظلم» على كل ذنب، فبيّن النبي ﷺ أن المراد هنا الشرك، واستشهد بآية لقمان.","en_h":"When the verse \"those who believed and did not mix their faith with wrongdoing\" was revealed, they said: \"Which of us does not wrong himself?\" He said: \"It is not as you say: not mixing their faith with wrongdoing means with shirk. Have you not heard what Luqman said to his son: Do not associate others with Allah; indeed shirk is a great wrong?\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":6,"ay":82,"x":"قَالَ اللَّهُ تَعَالَى: ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُولَئِكَ لَهُمُ الأمْنُ وَهُمْ مُهْتَدُونَ﴾ أَيْ: هَؤُلَاءِ الَّذِينَ أَخْلَصُوا الْعِبَادَةَ لِلَّهِ وَحْدَهُ لَا شَرِيكَ، لَهُ، وَلَمْ يُشْرِكُوا بِهِ شَيْئًا هُمُ الْآمِنُونَ يَوْمَ الْقِيَامَةِ، الْمُهْتَدُونَ فِي الدُّنْيَا وَالْآخِرَةِ.","en":"Allah said: \"Those who believed and did not mix their faith with wrongdoing, those will have security and they are guided\", that is, those who devoted worship to Allah alone with no partner and associated nothing with Him are the secure ones on the Day of Resurrection and the guided in this world and the next."}},{"id":"t2_238","ch":"tafsir","t":"الصلاة الوسطى","ay":[[2,238]],"h":[{"b":"muslim","n":"627","x":"شَغَلُونَا عَنِ الصَّلاَةِ الْوُسْطَى صَلاَةِ الْعَصْرِ مَلأَ اللَّهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا","gr":"صحيح: رواه مسلم"}],"f":"سمّى النبي ﷺ يوم الأحزاب الصلاة الوسطى بأنها صلاة العصر، فكان ذلك من أقوى ما استُدلّ به في تفسير الآية.","en_h":"On the day of al-Ahzab the Messenger of Allah ﷺ said: \"They kept us from the middle prayer, the Asr prayer; may Allah fill their houses and graves with fire.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":2,"ay":238,"x":"وَقِيلَ: إِنَّهَا صَلَاةُ الْعَصْرِ. قَالَ التِّرْمِذِيُّ وَالْبَغَوِيُّ، رَحِمَهُمَا اللَّهُ: وَهُوَ قَوْلُ أَكْثَرِ عُلَمَاءِ الصَّحَابَةِ وَغَيْرِهِمْ، وَقَالَ الْقَاضِي الْمَاوَرْدِيُّ: وَهُوَ قَوْلُ جُمْهُورِ التَّابِعِينَ.","en":"And it is said that it is the Asr prayer. Al-Tirmidhi and al-Baghawi, may Allah have mercy on them, said it is the view of most of the learned among the Companions and others, and al-Qadi al-Mawardi said it is the view of the majority of the Followers."}},{"id":"t8_60","ch":"tafsir","t":"القوة: الرمي","ay":[[8,60]],"h":[{"b":"muslim","n":"1917","x":"وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ أَلاَ إِنَّ الْقُوَّةَ الرَّمْىُ أَلاَ إِنَّ الْقُوَّةَ الرَّمْىُ أَلاَ إِنَّ الْقُوَّةَ الرَّمْىُ","gr":"صحيح: رواه مسلم"}],"f":"فسّر النبي ﷺ «القوة» في الآية بالرمي وكرّرها ثلاثاً تنبيهاً، وذلك من تفسير العام بأعظم أفراده.","en_h":"Uqba ibn Amir said: \"I heard the Messenger of Allah ﷺ say on the pulpit: Prepare against them whatever you can of power. Indeed, power is archery! Indeed, power is archery! Indeed, power is archery!\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":8,"ay":60,"x":"سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وسلم يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ: ﴿وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ﴾ أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ، أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ\" رَوَاهُ مُسْلِمٌ","en":"\"I heard the Messenger of Allah ﷺ say while on the pulpit: Prepare against them whatever you can of power. Indeed, power is archery! Indeed, power is archery!\" Narrated by Muslim."}},{"id":"t10_26","ch":"tafsir","t":"الزيادة: النظر إلى وجه الله","ay":[[10,26]],"h":[{"b":"muslim","n":"181","x":"إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ - قَالَ - يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى تُرِيدُونَ شَيْئًا أَزِيدُكُمْ فَيَقُولُونَ أَلَمْ تُبَيِّضْ وُجُوهَنَا أَلَمْ تُدْخِلْنَا الْجَنَّةَ وَتُنَجِّنَا مِنَ النَّارِ - قَالَ - فَيَكْشِفُ الْحِجَابَ فَمَا أُعْطُوا شَيْئًا أَحَبَّ إِلَيْهِمْ مِنَ النَّظَرِ إِلَى رَبِّهِمْ","gr":"صحيح: رواه مسلم"}],"f":"ثبت في الحديث أن «الزيادة» في الآية هي النظر إلى وجه الله الكريم، وهو أعظم نعيم أهل الجنة، وفي رواية لمسلم أن النبي ﷺ تلا بعد الحديث: «للذين أحسنوا الحسنى وزيادة».","en_h":"The Prophet ﷺ said: \"When the people of Paradise enter Paradise, Allah will say: Do you want anything more I may give you? They will say: Have You not whitened our faces, admitted us to Paradise and saved us from the Fire? Then the veil will be lifted, and they will have been given nothing more beloved to them than looking at their Lord.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":10,"ay":26,"x":"وَأَفْضَلُ مِنْ ذَلِكَ وَأَعْلَاهُ النظرُ إِلَى وَجْهِهِ الْكَرِيمِ، فَإِنَّهُ زِيَادَةٌ أَعْظَمُ مِنْ جَمِيعِ مَا أُعْطُوهُ، لَا يَسْتَحِقُّونَهَا بِعَمَلِهِمْ، بَلْ بِفَضْلِهِ وَرَحْمَتِهِ","en":"And the best and highest of that is looking at His noble Face, for it is an increase greater than everything they were given, which they do not deserve by their deeds but by His grace and mercy."}},{"id":"t84_8","ch":"tafsir","t":"الحساب اليسير: العرض","ay":[[84,7,8]],"h":[{"b":"bukhari","n":"6536","x":"مَنْ نُوقِشَ الْحِسَابَ عُذِّبَ \". قَالَتْ قُلْتُ أَلَيْسَ يَقُولُ اللَّهُ تَعَالَى {فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا}. قَالَ \" ذَلِكِ الْعَرْضُ","gr":"صحيح: رواه البخاري"}],"f":"سألت عائشة رضي الله عنها عن «الحساب اليسير» فبيّن النبي ﷺ أنه العرض على الله، أما من ناقش الله حسابه فقد هلك.","en_h":"The Prophet ﷺ said: \"Whoever is questioned in the reckoning is punished.\" Aisha said: \"Does Allah not say: He will be reckoned with an easy reckoning?\" He said: \"That is the presentation.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":84,"ay":8,"x":"لَيْسَ ذَاكَ بِالْحِسَابِ وَلَكِنَّ ذَلِكَ العَرْض، مَنْ نُوقِشَ الْحِسَابَ يَوْمَ الْقِيَامَةِ عُذِّبَ","en":"\"That is not the reckoning, but the presentation; whoever is examined in the reckoning on the Day of Resurrection is punished.\""}},{"id":"t2_143","ch":"tafsir","t":"الأمة الوسط شهداء على الناس","ay":[[2,143]],"h":[{"b":"bukhari","n":"4487","x":"يُدْعَى نُوحٌ يَوْمَ الْقِيَامَةِ فَيَقُولُ لَبَّيْكَ وَسَعْدَيْكَ يَا رَبِّ. فَيَقُولُ هَلْ بَلَّغْتَ فَيَقُولُ نَعَمْ. فَيُقَالُ لأُمَّتِهِ هَلْ بَلَّغَكُمْ فَيَقُولُونَ مَا أَتَانَا مِنْ نَذِيرٍ. فَيَقُولُ مَنْ يَشْهَدُ لَكَ فَيَقُولُ مُحَمَّدٌ وَأُمَّتُهُ. فَتَشْهَدُونَ أَنَّهُ قَدْ بَلَّغَ \". {وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا} فَذَلِكَ قَوْلُهُ جَلَّ ذِكْرُهُ {وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا} وَالْوَسَطُ الْعَدْلُ\"","gr":"صحيح: رواه البخاري"}],"f":"فسّر النبي ﷺ الشهادة في الآية بشهادة هذه الأمة لنوح والأنبياء بالبلاغ، وبيّن أن «الوسط» العدل.","en_h":"The Prophet ﷺ said that Nuh will be called on the Day of Resurrection and say: \"Here I am, O my Lord.\" He will ask: \"Did you convey?\" He will say yes, and his people will be asked, and they will say: \"No warner came to us.\" He will be asked for witnesses and will say: \"Muhammad and his community.\" They will testify that he conveyed. That is His saying: \"Thus We made you a middle nation\"; and the middle means just.","q":{"w":"ابن كثير","bk":"ibnkathir","s":2,"ay":143,"x":"وَقَوْلُهُ تَعَالَى: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ يَقُولُ تَعَالَى: إِنَّمَا حَوّلناكم إِلَى قِبْلَةِ إِبْرَاهِيمَ، عَلَيْهِ السَّلَامُ، وَاخْتَرْنَاهَا لَكُمْ لَنَجْعَلَكُمْ خِيَارَ الْأُمَمِ، لِتَكُونُوا يَوْمَ الْقِيَامَةِ شُهَداء عَلَى الْأُمَمِ؛ لِأَنَّ الْجَمِيعَ مُعْتَرِفُونَ لَكُمْ بِالْفَضْلِ.","en":"And His saying: \"Thus We made you a middle nation so you may be witnesses over mankind and the Messenger a witness over you\": Allah says that He turned you to the qibla of Ibrahim, peace be upon him, and chose it for you in order to make you the best of nations, so that on the Day of Resurrection you will be witnesses over the nations, because all of them acknowledge your excellence."}},{"id":"t40_60","ch":"tafsir","t":"الدعاء هو العبادة","ay":[[40,60]],"h":[{"b":"tirmidhi","n":"3372","x":"الدُّعَاءُ هُوَ الْعِبَادَةُ \" . ثُمَّ قَرَأََ : (وقالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ\"","gr":"رواه الترمذي · الحكم في مصدر البيانات — الألباني: صحيح؛ أحمد شاكر: صحيح؛ بشار عواد معروف: حسن صحيح؛ زبير علي زئي: صحيح"}],"f":"جعل النبي ﷺ الدعاء هو العبادة وقرأ الآية، فدل على أن ترك الدعاء استكبار عن العبادة وأن الدعاء أصل العبادة.","en_h":"The Prophet ﷺ said: \"Supplication is worship.\" Then he recited: And your Lord says: Call upon Me; I will respond to you. Indeed, those who are too proud to worship Me will enter Hell in humiliation.","q":{"w":"ابن كثير","bk":"ibnkathir","s":40,"ay":60,"x":"إِنَّ الدُّعَاءَ هُوَ الْعِبَادَةُ\" ثُمَّ قَرَأَ: ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ","en":"\"Supplication is worship.\" Then he recited: \"Call upon Me; I will respond to you. Indeed, those who are too proud to worship Me will enter Hell in humiliation.\""}},{"id":"t14_27","ch":"tafsir","t":"القول الثابت عند السؤال في القبر","ay":[[14,27]],"h":[{"b":"bukhari","n":"4699","x":"الْمُسْلِمُ إِذَا سُئِلَ فِي الْقَبْرِ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَذَلِكَ قَوْلُهُ {يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ}","gr":"صحيح: رواه البخاري"}],"f":"بيّن النبي ﷺ أن «القول الثابت» هو جواب المؤمن في القبر بالشهادتين، وأن الآية نزلت في عذاب القبر.","en_h":"The Prophet ﷺ said: \"When a Muslim is questioned in the grave he testifies that there is no god but Allah and that Muhammad is the Messenger of Allah. That is His saying: Allah keeps firm those who believe with the firm word in worldly life and in the Hereafter.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":14,"ay":27,"x":"اَلْمُسْلِمُ إِذَا سُئِلَ فِي الْقَبْرِ، شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَذَلِكَ قَوْلُهُ: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ","en":"\"When a Muslim is questioned in the grave, he testifies that there is no god but Allah and that Muhammad is the Messenger of Allah; that is His saying: Allah keeps firm those who believe with the firm word in worldly life and in the Hereafter.\""}},{"id":"t14_24","ch":"tafsir","t":"الكلمة الطيبة كشجرة طيبة: النخلة","ay":[[14,24,25]],"h":[{"b":"bukhari","n":"61","x":"إِنَّ مِنَ الشَّجَرِ شَجَرَةً لاَ يَسْقُطُ وَرَقُهَا، وَإِنَّهَا مَثَلُ الْمُسْلِمِ، فَحَدِّثُونِي مَا هِيَ \". فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي. قَالَ عَبْدُ اللَّهِ وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ، فَاسْتَحْيَيْتُ ثُمَّ قَالُوا حَدِّثْنَا مَا هِيَ يَا رَسُولَ اللَّهِ قَالَ \" هِيَ النَّخْلَةُ","gr":"صحيح: رواه البخاري"}],"f":"ضرب النبي ﷺ المثل بشجرة لا يسقط ورقها وبيّن أنها مثل المسلم، فبيّن المراد بالشجرة الطيبة في الآية: النخلة.","en_h":"The Prophet ﷺ said: \"Among trees there is one whose leaves do not fall, and it is like the Muslim; tell me what it is.\" People thought of the trees of the desert. Ibn Umar said: \"It came to my mind that it was the date palm, but I was shy.\" They said: \"Tell us, O Messenger of Allah.\" He said: \"It is the date palm.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":14,"ay":24,"x":"إِنَّ ذَلِكَ عِبَارَةٌ عَنِ الْمُؤْمِنِ، وَقَوْلِهِ الطَّيِّبِ، وَعَمَلِهِ الصَّالِحِ، وَإِنَّ الْمُؤْمِنَ كَالشَّجَرَةِ مِنَ النَّخْلِ، لَا يَزَالُ يُرْفَعُ لَهُ عَمَلٌ صَالِحٌ فِي كُلِّ حِينٍ وَوَقْتٍ، وَصَبَاحٍ وَمَسَاءٍ","en":"That is an expression for the believer, his good word and his righteous deed, and the believer is like the date palm tree: a righteous deed is continually raised for him at every time and moment, morning and evening."}},{"id":"t17_79","ch":"tafsir","t":"المقام المحمود","ay":[[17,79]],"h":[{"b":"bukhari","n":"7440","x":"ثُمَّ تَلاَ هَذِهِ الآيَةَ {عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا} قَالَ وَهَذَا الْمَقَامُ الْمَحْمُودُ الَّذِي وُعِدَهُ نَبِيُّكُمْ","gr":"صحيح: رواه البخاري"}],"f":"ختم قتادة حديث الشفاعة الطويل بأن النبي ﷺ تلا الآية وقال إن هذا هو المقام المحمود الذي وعده الله نبيه، أي مقام الشفاعة.","en_h":"In the hadith of intercession, Qatada related: \"Then he recited the verse: It may be that your Lord will raise you to a Praised Station. And this is the Praised Station that your Prophet ﷺ was promised.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":17,"ay":79,"x":"وَقَالَ ابْنُ عَبَّاسٍ: هَذَا الْمَقَامُ الْمَحْمُودُ مَقَامُ الشَّفَاعَةِ. وَكَذَا قَالَ ابْنُ أَبِي نَجِيح، عَنْ مُجَاهِدٍ. وَقَالَهُ الْحَسَنُ الْبَصْرِيُّ.","en":"Ibn Abbas said: \"This Praised Station is the station of intercession.\" Ibn Abi Najih said the same from Mujahid, and al-Hasan al-Basri said it too."}},{"id":"t108","ch":"tafsir","t":"الكوثر: نهر في الجنة","ay":[[108,1,3]],"h":[{"b":"bukhari","n":"4964","x":"أَتَيْتُ عَلَى نَهَرٍ حَافَتَاهُ قِبَابُ اللُّؤْلُؤِ مُجَوَّفًا فَقُلْتُ مَا هَذَا يَا جِبْرِيلُ قَالَ هَذَا الْكَوْثَرُ","gr":"صحيح: رواه البخاري"}],"f":"فسّر النبي ﷺ الكوثر في ليلة المعراج بأنه نهر في الجنة حافتاه قباب اللؤلؤ المجوف.","en_h":"The Prophet ﷺ said: \"I came upon a river whose banks had domes of hollow pearl, and I said: What is this, O Jibril? He said: This is al-Kawthar.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":108,"ay":1,"x":"هُوَ نَهْرٌ أَعْطَانِيهِ رَبِّي، عَزَّ وَجَلَّ، فِي الْجَنَّةِ، عَلَيْهِ خَيْرٌ كَثِيرٌ، تردُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ، آنِيَتُهُ عَدَدَ الْكَوَاكِبِ","en":"\"It is a river my Lord, Mighty and Majestic, gave me in Paradise; it has abundant good; my community will come to it on the Day of Resurrection; its vessels are as many as the stars.\""}},{"id":"t3_7","ch":"tafsir","t":"المحكم والمتشابه: من يتبع المتشابه","ay":[[3,7]],"h":[{"b":"bukhari","n":"4547","x":"فَإِذَا رَأَيْتَ الَّذِينَ يَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ، فَأُولَئِكَ الَّذِينَ سَمَّى اللَّهُ، فَاحْذَرُوهُمْ","gr":"صحيح: رواه البخاري"}],"f":"تلا النبي ﷺ الآية وبيّن أن من يتتبع المتشابه هم الذين سمّاهم الله، وأمر بالحذر منهم.","en_h":"Aisha said: \"The Messenger of Allah ﷺ recited this verse: He it is who sent down to you the Book... He said: When you see those who follow what is ambiguous in it, those are the ones Allah named, so beware of them.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":3,"ay":7,"x":"﴿فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ﴾ أَيْ: ضَلَالٌ وَخُرُوجٌ عَنِ الْحَقِّ إِلَى الْبَاطِلِ ﴿فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ﴾ أَيْ: إِنَّمَا يَأْخُذُونَ مِنْهُ بِالْمُتَشَابِهِ الَّذِي يُمْكِنُهُمْ أَنْ يُحَرِّفُوهُ إِلَى مَقَاصِدِهِمُ الْفَاسِدَةِ، وَيُنْزِلُوهُ عَلَيْهَا، لِاحْتِمَالِ لَفْظِهِ لِمَا يَصْرِفُونَهُ فَأَمَّا الْمُحْكَمُ فَلَا نَصِيبَ لَهُمْ فِيهِ؛ لِأَنَّهُ دَامِغٌ لَهُمْ وَحُجَّةٌ عَلَيْهِمْ، وَلِهَذَا قَالَ: ﴿ابْتِغَاءَ الْفِتْنَةِ﴾ أَيِ: الْإِضْلَالِ لِأَتْبَاعِهِمْ، إِيهَامًا لَهُمْ أَنَّهُمْ يَحْتَجُّونَ عَلَى بِدْعَتِهِمْ بِالْقُرْآنِ، وَهَذَا حُجَّةٌ عَلَيْهِمْ لَا لَهُمْ","en":"\"As for those in whose hearts is deviation\": that is, misguidance and departure from the truth to falsehood, \"they follow what is ambiguous of it\": they only take of it the ambiguous that they can twist toward their corrupt aims and apply it to them because its wording could carry what they turn it to; as for the clear, they have no share in it because it crushes them and is a proof against them. That is why Allah said \"seeking discord\", meaning leading their followers astray, giving them the impression that they argue for their innovation from the Quran, but this is a proof against them, not for them."}},{"id":"t53_13","ch":"tafsir","t":"من رآه النبي ﷺ عند سدرة المنتهى","ay":[[53,13,18]],"h":[{"b":"muslim","n":"177","x":"إِنَّمَا هُوَ جِبْرِيلُ لَمْ أَرَهُ عَلَى صُورَتِهِ الَّتِي خُلِقَ عَلَيْهَا غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ رَأَيْتُهُ مُنْهَبِطًا مِنَ السَّمَاءِ سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ إِلَى الأَرْضِ","gr":"صحيح: رواه مسلم"}],"f":"سألت عائشة رضي الله عنها النبي ﷺ عن قوله «ولقد رآه نزلة أخرى» فبيّن أن المرئي جبريل عليه السلام على صورته التي خُلق عليها.","en_h":"The Prophet ﷺ said: \"It is only Jibril. I did not see him in his true form in which he was created except these two times: I saw him descending from the heaven, filling what is between the sky and the earth with the greatness of his creation.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":53,"ay":13,"x":"أَنَّ مُحَمَّدًا ﷺ رَأَى جِبْرِيلَ لَهُ سِتُّمِائَةِ جَنَاحٍ","en":"\"Muhammad ﷺ saw Jibril, who had six hundred wings.\""}},{"id":"t83_6","ch":"tafsir","t":"يوم يقوم الناس لرب العالمين","ay":[[83,4,6]],"h":[{"b":"bukhari","n":"4938","x":"يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ} حَتَّى يَغِيبَ أَحَدُهُمْ فِي رَشْحِهِ إِلَى أَنْصَافِ أُذُنَيْهِ","gr":"صحيح: رواه البخاري"}],"f":"وصف النبي ﷺ هول الوقوف يوم القيامة بأن العرق يبلغ بالناس إلى أنصاف آذانهم.","en_h":"The Prophet ﷺ said about \"the Day when mankind will stand before the Lord of the worlds\": \"Until one of them is submerged in his sweat up to the middle of his ears.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":83,"ay":6,"x":"قَالَ الْإِمَامُ مَالِكٌ: عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ أَنَّ النَّبِيَّ ﷺ قَالَ: \" ﴿يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ﴾ حَتَّى يَغِيبَ أَحَدُهُمْ فِي رَشْحِهِ إِلَى أَنْصَافِ أُذُنَيْهِ\".","en":"Imam Malik narrated from Nafi from Ibn Umar that the Prophet ﷺ said: \"The Day when mankind will stand before the Lord of the worlds\" - until one of them is submerged in his sweat up to the middle of his ears."}},{"id":"t15_87","ch":"tafsir","t":"السبع المثاني: الفاتحة","ay":[[15,87],[1,1,7]],"h":[{"b":"bukhari","n":"4474","x":"لأُعَلِّمَنَّكَ سُورَةً هِيَ أَعْظَمُ سُورَةٍ فِي الْقُرْآنِ \". قَالَ \" {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُوتِيتُهُ","gr":"صحيح: رواه البخاري"}],"f":"بيّن النبي ﷺ أن الفاتحة هي «السبع المثاني والقرآن العظيم» الواردة في الآية، فهي أعظم سورة في القرآن.","en_h":"The Prophet ﷺ said to Abu Sa'id ibn al-Mu'alla: \"I will teach you a surah that is the greatest surah in the Quran.\" He said: \"Praise be to Allah, Lord of the worlds: it is the seven oft-repeated verses and the great Quran which I was given.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":15,"ay":87,"x":"وَالْقَوْلُ الثَّانِي: أَنَّهَا الْفَاتِحَةُ، وَهِيَ سَبْعُ آيَاتٍ. رُوي ذَلِكَ عَنْ عُمَرَ وَعَلِيٍّ، وَابْنِ مَسْعُودٍ، وَابْنِ عَبَّاسٍ. قَالَ ابْنُ عَبَّاسٍ: وَالْبَسْمَلَةُ هِيَ الْآيَةُ السَّابِعَةُ، وَقَدْ خَصَّكُمُ اللَّهُ بِهَا.","en":"The second view is that it is al-Fatiha, which has seven verses. This is reported from Umar, Ali, Ibn Mas'ud and Ibn Abbas. Ibn Abbas said: \"The basmala is the seventh verse, and Allah has singled you out with it.\""}},{"id":"t32_17","ch":"tala","t":"ما أخفي للصالحين","ay":[[32,17]],"h":[{"b":"bukhari","n":"3244","x":"أَعْدَدْتُ لِعِبَادِي الصَّالِحِينَ مَا لاَ عَيْنَ رَأَتْ، وَلاَ أُذُنَ سَمِعَتْ، وَلاَ خَطَرَ عَلَى قَلْبِ بَشَرٍ، فَاقْرَءُوا إِنْ شِئْتُمْ {فَلاَ تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ}","gr":"صحيح: رواه البخاري"}],"f":"أخبر النبي ﷺ عن الله أنه أعدّ للصالحين ما لا يخطر على قلب بشر، ثم أحال إلى الآية التي تصدّق ذلك.","en_h":"The Prophet ﷺ said: \"Allah said: I have prepared for My righteous servants what no eye has seen, no ear has heard and no human heart has imagined. Recite if you wish: No soul knows what has been hidden for them of comfort for the eyes.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":32,"ay":17,"x":"وَقَوْلُهُ: ﴿فَلا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ﴾ أَيْ: فَلَا يَعْلَمُ أَحَدٌ عَظَمَةَ مَا أَخْفَى اللَّهُ لَهُمْ فِي الْجَنَّاتِ مِنَ النَّعِيمِ الْمُقِيمِ، وَاللَّذَّاتِ الَّتِي لَمْ يَطَّلِعُ عَلَى مِثْلِهَا أَحَدٌ، لَمَّا أَخْفَوْا أَعْمَالَهُمْ أَخْفَى اللَّهُ لَهُمْ مِنَ الثَّوَابِ، جَزَاءً وِفَاقًا؛ فَإِنَّ الْجَزَاءَ مِنْ جِنْسِ الْعَمَلِ.","en":"\"No soul knows what has been hidden for them of comfort for the eyes as reward for what they used to do\", that is: no one knows the greatness of what Allah has hidden for them in the Gardens of lasting bliss and pleasures the like of which no one has seen; since they hid their deeds, Allah hid for them a reward, a fitting recompense, for the recompense is of the same kind as the deed."}},{"id":"t56_30","ch":"tala","t":"الظل الممدود في الجنة","ay":[[56,27,30]],"h":[{"b":"bukhari","n":"3252","x":"إِنَّ فِي الْجَنَّةِ لَشَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ، وَاقْرَءُوا إِنْ شِئْتُمْ {وَظِلٍّ مَمْدُودٍ}","gr":"صحيح: رواه البخاري"}],"f":"استدل النبي ﷺ بالآية على عظم شجر الجنة، فقال إن الراكب يسير في ظل الشجرة مئة سنة، «واقرؤوا إن شئتم: وظل ممدود».","en_h":"The Prophet ﷺ said: \"In Paradise there is a tree in whose shade a rider travels for a hundred years, and recite if you wish: And extended shade.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":56,"ay":30,"x":"إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا","en":"\"In Paradise there is a tree in whose shade a rider travels for a hundred years without crossing it.\""}},{"id":"t47_22","ch":"tala","t":"صلة الرحم","ay":[[47,22,23]],"h":[{"b":"bukhari","n":"4830","x":"خَلَقَ اللَّهُ الْخَلْقَ، فَلَمَّا فَرَغَ مِنْهُ قَامَتِ الرَّحِمُ فَأَخَذَتْ بِحَقْوِ الرَّحْمَنِ فَقَالَ لَهَا مَهْ. قَالَتْ هَذَا مَقَامُ الْعَائِذِ بِكَ مِنَ الْقَطِيعَةِ. قَالَ أَلاَ تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ. قَالَتْ بَلَى يَا رَبِّ. قَالَ فَذَاكِ لَكِ \". قَالَ أَبُو هُرَيْرَةَ اقْرَءُوا إِنْ شِئْتُمْ {فهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ\"}","gr":"صحيح: رواه البخاري"}],"f":"أخبر النبي ﷺ أن الرحم تعلّقت بالرحمن تستعيذ من القطيعة، وقال أبو هريرة «اقرؤوا إن شئتم» وتلا الآية في التحذير من قطعها.","en_h":"The Prophet ﷺ said: \"Allah created the creation, and when He finished, the womb stood up and said: This is the place of one seeking refuge in You from being severed. He said: Are you not pleased that I join whoever joins you and sever whoever severs you? It said: Yes. He said: That is yours.\" Abu Hurayra said: \"Recite if you wish: Would you then, if you turned away, cause corruption in the earth and sever your ties of kinship?\"","q":{"w":"السعدي","bk":"saadi","s":47,"ay":22,"x":"{22} ثم ذكر تعالى حال المتولِّي عن طاعة ربِّه، وأنَّه لا يتولَّى إلى خيرٍ، بل إلى شرٍّ، فقال:{فهل عسيتُمۡ إن تَوَلَّيۡتُم أن تفسدوا في الأرض وتقطِّعوا أرحامكم}؛ أي: فهما أمران: إمَّا التزامٌ لطاعة الله وامتثالٌ لأوامره؛ فثَمَّ الخيرُ والرشدُ والفلاح.","en":"{22} Then He mentions the state of the one who turns away from obedience to his Lord, and that he turns not to good but to evil, so He said: \"Would you then, if you turned away, cause corruption in the earth and sever your ties of kinship?\" That is, there are two matters: either commitment to obeying Allah and complying with His commands, and then there is good, right guidance and success."}},{"id":"t33_6","ch":"tala","t":"النبي أولى بالمؤمنين من أنفسهم","ay":[[33,6]],"h":[{"b":"bukhari","n":"2399","x":"مَا مِنْ مُؤْمِنٍ إِلاَّ وَأَنَا أَوْلَى بِهِ فِي الدُّنْيَا وَالآخِرَةِ اقْرَءُوا إِنْ شِئْتُمْ {النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ}","gr":"صحيح: رواه البخاري"}],"f":"قال النبي ﷺ إنه أولى بكل مؤمن في الدنيا والآخرة وتلا الآية، ثم بيّن حكم من مات وترك ديناً أو مالاً.","en_h":"The Prophet ﷺ said: \"There is no believer but I am closest to him in this world and the next. Recite if you wish: The Prophet is closer to the believers than their own selves.\"","q":{"w":"السعدي","bk":"saadi","s":33,"ay":6,"x":"يخبر تعالى المؤمنين خبراً يعرِفون به حالة الرسول - صلى الله عليه وسلم - ومرتَبَتَه، فيعامِلونه يمقتضى تلك الحالة، فقال:{النبيُّ أولى بالمؤمنين من أنفُسِهم}: أقرب ما للإنسان وأولى ما له نفسُه؛ فالرسولُ أولى به من نفسِهِ؛ لأنَّه عليه الصلاة والسلام بَذَلَ لهم من النُّصح والشفقة والرأفة ما كان به أرحم الخلق وأرأفهم","en":"{6} Allah informs the believers of a report by which they know the state and rank of the Messenger ﷺ so they treat him accordingly, and said: \"The Prophet is closer to the believers than their own selves\": the closest thing to a person and the dearest to him is himself, yet the Messenger is closer to him than himself, because he gave them of counsel, compassion and tenderness what made him the most merciful and most tender of creation."}},{"id":"t11_102","ch":"tala","t":"أخذ الله للظالم","ay":[[11,102]],"h":[{"b":"bukhari","n":"4686","x":"إِنَّ اللَّهَ لَيُمْلِي لِلظَّالِمِ حَتَّى إِذَا أَخَذَهُ لَمْ يُفْلِتْهُ \". قَالَ ثُمَّ قَرَأَ {وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهْىَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ\"}","gr":"صحيح: رواه البخاري"}],"f":"أخبر النبي ﷺ أن الله يمهل الظالم حتى إذا أخذه لم يفلته، وقرأ الآية شاهداً.","en_h":"The Prophet ﷺ said: \"Allah gives the wrongdoer respite until, when He seizes him, he does not let him escape.\" Then he recited: And such is the seizure of your Lord when He seizes the towns while they are wrongdoing; indeed His seizure is painful and severe.","q":{"w":"ابن كثير","bk":"ibnkathir","s":11,"ay":102,"x":"يَقُولُ تَعَالَى: وَكَمَا أَهْلَكْنَا أُولَئِكَ الْقُرُونَ الظَّالِمَةَ الْمُكَذِّبَةَ لِرُسُلِنَا كَذَلِكَ نَفْعَلُ بِنَظَائِرِهِمْ وَأَشْبَاهِهِمْ وَأَمْثَالِهِمْ، ﴿إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ﴾ وَفِي الصَّحِيحَيْنِ عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: \"إِنَّ اللَّهَ ليُملي لِلظَّالِمِ، حَتَّى إِذَا أَخَذَهُ لَمْ يُفلته\"، ثُمَّ قَرَأَ رَسُولُ اللَّهِ ﷺ: ﴿وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ﴾ .","en":"Allah says: Just as We destroyed those wrongdoing generations that denied Our messengers, so We do to their likes, \"indeed His seizure is painful and severe\". And in the two Sahihs from Abu Musa al-Ash'ari: the Messenger of Allah ﷺ said: \"Allah gives the wrongdoer respite until, when He seizes him, He does not let him escape.\" Then the Messenger of Allah ﷺ recited: \"And such is the seizure of your Lord when He seizes the towns while they are wrongdoing; indeed His seizure is painful and severe.\""}},{"id":"t21_104","ch":"tala","t":"حشر الناس حفاة عراة","ay":[[21,104]],"h":[{"b":"bukhari","n":"3349","x":"إِنَّكُمْ مَحْشُورُونَ حُفَاةً عُرَاةً غُرْلاً ـ ثُمَّ قَرَأَ – {كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ}","gr":"صحيح: رواه البخاري"}],"f":"خطب النبي ﷺ فأخبر بحال الحشر، وتلا الآية تصديقاً لأن الإعادة كالبدء وعد من الله.","en_h":"The Prophet ﷺ said: \"You will be gathered barefoot, unclothed and uncircumcised.\" Then he recited: As We began the first creation, We will repeat it; a promise upon Us; indeed We are doers.","q":{"w":"السعدي","bk":"saadi","s":21,"ay":104,"x":"{104} يخبر تعالى أنه يوم القيامة يطوي السماواتِ على عِظَمها واتِّساعها كما يطوي الكاتُب للسجل؛ أي:الورقة المكتوب فيها؛ فتنتثر نجومها، وتكور شمسها وقمرها، وتزول عن أماكنها.{كما بَدَأنا أوَّلَ خلقٍ نعيدُه}؛ أي: إعادتنا للخلق مثل ابتدائنا لخلقهم؛ فكما ابتدأنا خلقَهم ولم يكونوا شيئاً؛ كذلك نعيدُهم بعد موتهم، {وعداً علينا إنَّا كنَّا فاعلينَ}: ننفِّذُ ما وَعَدْنا؛ لكمال قدرتِهِ، وأنه لا تمتنعُ منه الأشياء.","en":"{104} Allah informs that on the Day of Resurrection He will roll up the heavens, for all their greatness and vastness, as a scribe rolls up a scroll, the written sheet; its stars will scatter, its sun and moon will be wrapped up, and it will move from its places. \"As We began the first creation, We will repeat it\", that is, our repeating creation is like our beginning it: as we began them when they were nothing, so we will bring them back after their death; \"a promise upon Us; indeed We are doers\", we carry out what We promised, through the perfection of His power and that nothing is beyond Him."}},{"id":"f_fatiha","ch":"fadl","t":"فاتحة الكتاب وخواتيم البقرة نوران","ay":[[1,1,7],[2,285,286]],"h":[{"b":"muslim","n":"806","x":"أَبْشِرْ بِنُورَيْنِ أُوتِيتَهُمَا لَمْ يُؤْتَهُمَا نَبِيٌّ قَبْلَكَ فَاتِحَةُ الْكِتَابِ وَخَوَاتِيمُ سُورَةِ الْبَقَرَةِ لَنْ تَقْرَأَ بِحَرْفٍ مِنْهُمَا إِلاَّ أُعْطِيتَهُ","gr":"صحيح: رواه مسلم"}],"f":"بشّر مَلَك النبيَّ ﷺ بنورين لم يُؤتهما نبي قبله: فاتحة الكتاب وخواتيم سورة البقرة.","en_h":"Ibn Abbas said that while Jibril was sitting with the Prophet ﷺ he heard a sound above and an angel who had never descended before said: \"Receive glad tidings of two lights given to you and to no prophet before you: the Opening of the Book and the last verses of al-Baqara. You will not recite a letter of them but you will be given it.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":2,"ay":285,"x":"أبشر بنورين قد أوتيتهما، لم يؤتهما نبي قبلك: فاتحة الكتاب، وخواتيم سُورَةِ الْبَقَرَةِ، لَنْ تَقْرَأَ حَرْفًا مِنْهُمَا إِلَّا أُوتِيتُهُ","en":"\"Receive glad tidings of two lights you have been given, which no prophet before you was given: the Opening of the Book and the closing verses of Surat al-Baqara; you will not recite a letter of them but you will be given it.\""}},{"id":"f_kursi","ch":"fadl","t":"آية الكرسي","ay":[[2,255]],"h":[{"b":"bukhari","n":"2311","x":"إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ} حَتَّى تَخْتِمَ الآيَةَ، فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ","gr":"صحيح: رواه البخاري"}],"f":"علّم الشيطان أبا هريرة وهو سارق أن قراءة آية الكرسي عند النوم تحفظ، فأقرّه النبي ﷺ وقال: صدقك وهو كذوب.","en_h":"In the account of Abu Hurayra and the one who came to steal food: \"When you go to your bed, recite Ayat al-Kursi, for there will remain over you a guard from Allah and no devil will come near you until morning.\"","q":{"w":"القرطبي","bk":"qurtubi","s":2,"ay":255,"x":"هَذِهِ آيَةُ الْكُرْسِيِّ سَيِّدَةُ آيِ الْقُرْآنِ وَأَعْظَمُ آيَةٍ","en":"This is Ayat al-Kursi, the master of the verses of the Quran and the greatest verse."}},{"id":"f_baqara2","ch":"fadl","t":"الآيتان من آخر سورة البقرة","ay":[[2,285,286]],"h":[{"b":"bukhari","n":"5009","x":"مَنْ قَرَأَ بِالآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ","gr":"صحيح: رواه البخاري"}],"f":"ورد أن من قرأ الآيتين الأخيرتين من البقرة في ليلة كفتاه؛ وللعلماء في معنى «كفتاه» أقوال ذكرها شراح الحديث.","en_h":"The Prophet ﷺ said: \"Whoever recites the last two verses of Surat al-Baqara at night, they will suffice him.\"","q":{"w":"القرطبي","bk":"qurtubi","s":2,"ay":285,"x":"وَقِيلَ: كَفَتَاهُ مِنْ شَرِّ الشَّيْطَانِ فَلَا يكون له سُلْطَانٌ","en":"And it is said: they suffice him against the evil of the devil, so that he has no power."}},{"id":"f_ikhlas","ch":"fadl","t":"سورة الإخلاص تعدل ثلث القرآن","ay":[[112,1,4]],"h":[{"b":"bukhari","n":"5013","x":"وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ","gr":"صحيح: رواه البخاري"}],"f":"سمع رجل رجلاً يردد «قل هو الله أحد» فاستقلّها، فأخبر النبي ﷺ أنها تعدل ثلث القرآن لما اشتملت عليه من التوحيد.","en_h":"A man heard another reciting \"Say: He is Allah, One\" repeatedly. In the morning he came to the Prophet ﷺ and mentioned it, thinking it little. The Messenger of Allah ﷺ said: \"By Him in whose hand is my soul, it equals a third of the Quran.\"","q":{"w":"القرطبي","bk":"qurtubi","s":112,"ay":1,"x":"قَالَ بَعْضُ الْعُلَمَاءِ: إِنَّهَا عَدَلَتْ ثُلُثَ الْقُرْآنِ لِأَجْلِ هَذَا الِاسْمِ، الَّذِي هُوَ الصَّمَدُ، فَإِنَّهُ لَا يُوجَدُ فِي غَيْرِهَا مِنَ السور","en":"Some scholars said: it equals a third of the Quran because of this name, which is al-Samad, for it is not found in any other surah."}},{"id":"f_muawwidhat","ch":"fadl","t":"المعوّذتان","ay":[[113,1,5],[114,1,6]],"h":[{"b":"muslim","n":"814","x":"أَلَمْ تَرَ آيَاتٍ أُنْزِلَتِ اللَّيْلَةَ لَمْ يُرَ مِثْلُهُنَّ قَطُّ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ}","gr":"صحيح: رواه مسلم"}],"f":"أخبر النبي ﷺ عقبة بن عامر بأن آيات أُنزلت الليلة لم يُر مثلهن قط، وهي «قل أعوذ برب الفلق» و«قل أعوذ برب الناس».","en_h":"The Prophet ﷺ said: \"Have you not seen the verses revealed tonight, the like of which has never been seen: Say: I seek refuge in the Lord of daybreak, and Say: I seek refuge in the Lord of mankind.\"","q":{"w":"القرطبي","bk":"qurtubi","s":113,"ay":1,"x":"فَقَرَأَهُنَّ رَسُولِ اللَّهِ ﷺ، ثُمَّ قَالَ: لَمْ يَتَعَوَّذِ النَّاسُ بِمِثْلِهِنَّ، أَوْ لَا يَتَعَوَّذُ النَّاسُ بِمِثْلِهِنَّ","en":"The Messenger of Allah ﷺ recited them, then said: \"People have not sought refuge with the like of them,\" or \"People do not seek refuge with the like of them.\""}},{"id":"f_kahf","ch":"fadl","t":"عشر آيات من أول الكهف","ay":[[18,1,7]],"h":[{"b":"muslim","n":"809","x":"مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ","gr":"صحيح: رواه مسلم"}],"f":"ورد أن من حفظ عشر آيات من أول الكهف عُصم من فتنة الدجال.","en_h":"The Prophet ﷺ said: \"Whoever memorizes ten verses from the beginning of Surat al-Kahf will be protected from the Dajjal.\"","q":{"w":"القرطبي","bk":"qurtubi","s":18,"ay":1,"x":"وَفِي صَحِيحِ مُسْلِمٍ عَنْ أَبِي الدَّرْدَاءِ أَنَّ نَبِيَّ اللَّهِ ﷺ قَالَ: \"مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ","en":"And in Sahih Muslim, from Abu al-Darda: the Prophet of Allah ﷺ said: \"Whoever memorizes ten verses from the beginning of Surat al-Kahf is protected from the Dajjal.\""}},{"id":"f_mulk","ch":"fadl","t":"سورة الملك","ay":[[67,1,5]],"h":[{"b":"tirmidhi","n":"2891","x":"إِنَّ سُورَةً مِنَ الْقُرْآنِ ثَلاَثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ وَهِيَ سُورَةُ تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ","gr":"رواه الترمذي · الحكم في مصدر البيانات — الألباني: حسن؛ أحمد شاكر: حسن؛ بشار عواد معروف: حسن؛ زبير علي زئي: إسناده حسن"}],"f":"سورة الملك ثلاثون آية، وقد ورد أنها تشفع لقارئها حتى يُغفر له؛ والحديث في سنن الترمذي بدرجته المبيّنة أدناه.","en_h":"The Prophet ﷺ said: \"There is a surah in the Quran of thirty verses that interceded for a man until he was forgiven: it is Blessed is He in whose hand is the dominion.\"","q":{"w":"القرطبي","bk":"qurtubi","s":67,"ay":1,"x":"وَعَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ ﷺ: (إِنَّ سُورَةً مِنْ كِتَابِ اللَّهِ مَا هِيَ إِلَّا ثَلَاثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى أَخْرَجَتْهُ مِنَ النَّارِ يَوْمَ الْقِيَامَةِ وَأَدْخَلَتْهُ الْجَنَّةَ وَهِيَ سُورَةُ \"تَبَارَكَ\").","en":"And from Abu Hurayra, who said: the Prophet ﷺ said: \"A surah of the Book of Allah, only thirty verses, interceded for a man until it brought him out of the Fire on the Day of Resurrection and admitted him to Paradise; it is Surat Tabarak.\""}},{"id":"f_baqara","ch":"fadl","t":"سورة البقرة وطرد الشيطان","ay":[[2,1,5]],"h":[{"b":"muslim","n":"780","x":"لاَ تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ","gr":"صحيح: رواه مسلم"}],"f":"أمر النبي ﷺ بقراءة القرآن في البيوت وأخبر أن الشيطان ينفر من البيت الذي تُقرأ فيه سورة البقرة.","en_h":"The Prophet ﷺ said: \"Do not make your houses graves; the devil flees from the house in which Surat al-Baqara is recited.\"","q":{"w":"القرطبي","bk":"qurtubi","s":2,"ay":1,"x":"وَرُوِيَ أَيْضًا عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: (لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ).","en":"And it was also narrated from Abu Hurayra that the Messenger of Allah ﷺ said: \"Do not make your houses graves; the devil flees from the house in which Surat al-Baqara is recited.\""}},{"id":"f_fath","ch":"fadl","t":"سورة الفتح","ay":[[48,1,3]],"h":[{"b":"bukhari","n":"4177","x":"لَقَدْ أُنْزِلَتْ عَلَىَّ اللَّيْلَةَ سُورَةٌ لَهِيَ أَحَبُّ إِلَىَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ","gr":"صحيح: رواه البخاري"}],"f":"أخبر النبي ﷺ أنه أُنزلت عليه سورة هي أحبّ إليه من الدنيا وما فيها، ثم قرأ «إنا فتحنا لك فتحاً مبيناً».","en_h":"The Prophet ﷺ said: \"A surah has been revealed to me tonight that is dearer to me than all that the sun rises upon.\" Then he recited: Indeed, We have given you a clear conquest.","q":{"w":"ابن كثير","bk":"ibnkathir","s":48,"ay":1,"x":"نَزَلَتْ عَلَيَّ اللَّيْلَةَ سُورَةٌ هِيَ أَحَبُّ إِلَيَّ مِنَ الدُّنْيَا وَمَا فِيهَا: ﴿إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا","en":"\"A surah was revealed to me tonight that is dearer to me than the world and all that is in it: Indeed, We have given you a clear conquest.\""}},{"id":"a_shuara","ch":"asbab","t":"وأنذر عشيرتك الأقربين","ay":[[26,214,216],[111,1,3]],"h":[{"b":"bukhari","n":"4770","x":"لَمَّا نَزَلَتْ {وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ} صَعِدَ النَّبِيُّ صلى الله عليه وسلم عَلَى الصَّفَا فَجَعَلَ يُنَادِي \" يَا بَنِي فِهْرٍ، يَا بَنِي عَدِيٍّ \". لِبُطُونِ قُرَيْشٍ حَتَّى اجْتَمَعُوا، فَجَعَلَ الرَّجُلُ إِذَا لَمْ يَسْتَطِعْ أَنْ يَخْرُجَ أَرْسَلَ رَسُولاً لِيَنْظُرَ مَا هُوَ، فَجَاءَ أَبُو لَهَبٍ وَقُرَيْشٌ فَقَالَ \" أَرَأَيْتَكُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ خَيْلاً بِالْوَادِي تُرِيدُ أَنْ تُغِيرَ عَلَيْكُمْ، أَكُنْتُمْ مُصَدِّقِيَّ \". قَالُوا نَعَمْ، مَا جَرَّبْنَا عَلَيْكَ إِلاَّ صِدْقًا. قَالَ \" فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ \". فَقَالَ أَبُو لَهَبٍ تَبًّا لَكَ سَائِرَ الْيَوْمِ، أَلِهَذَا جَمَعْتَنَا فَنَزَلَتْ {تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ * مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ}","gr":"صحيح: رواه البخاري"}],"f":"لما نزلت الآية صعد النبي ﷺ الصفا فنادى قريشاً وأنذرهم، فاعترض أبو لهب فنزلت «تبّت يدا أبي لهب».","en_h":"Ibn Abbas said: \"When the verse, And warn your closest kindred, was revealed, the Prophet ﷺ climbed al-Safa and called: O Banu Fihr, O Banu Adi! until they gathered. He said: If I told you that cavalry in the valley were about to raid you, would you believe me? They said: Yes. He said: I am a warner to you before a severe punishment. Abu Lahab said: May you perish for the rest of the day! Is it for this that you gathered us? Then Perish the hands of Abu Lahab was revealed.\"","q":{"w":"السعدي","bk":"saadi","s":26,"ay":214,"x":"{214} ولمَّا أمره بما فيه كمالُ نفسه؛ أمَرَه بتكميل غيره، فقال:{وأنذِرۡ عشيرتَكَ الأقربينَ}: الذين هم أقربُ الناس إليك، وأحقُّهم بإحسانك الدينيِّ والدنيويِّ، وهذا لا ينافي أمره بإنذار جميع الناس؛ كما إذا أُمِرَ الإنسان بعموم الإحسان، ثم قيل له: أحسن إلى قرابتِكَ؛ فيكون هذا الخصوص دالًّا على التأكيد وزيادة الحثِّ.","en":"{214} And when He commanded him with what perfects himself, He commanded him to perfect others, so He said: \"And warn your closest kindred\": those who are the closest of people to you and most deserving of your religious and worldly kindness; and this does not contradict His command to warn all people, as when a person is commanded with general kindness and then told: be kind to your relatives, so this specification indicates emphasis and added urging."}},{"id":"a_tawba","ch":"asbab","t":"النهي عن الاستغفار للمشركين","ay":[[9,113]],"h":[{"b":"bukhari","n":"4675","x":"لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ \". فَنَزَلَتْ {مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ\"}","gr":"صحيح: رواه البخاري"}],"f":"قال النبي ﷺ لعمه عند موته إنه سيستغفر له ما لم يُنهَ، فنزل النهي عن الاستغفار للمشركين.","en_h":"The Prophet ﷺ said: \"I will seek forgiveness for you as long as I am not forbidden.\" Then it was revealed: It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they be close relatives, after it has become clear to them that they are companions of Hellfire.","q":{"w":"القرطبي","bk":"qurtubi","s":9,"ay":113,"x":"فَقَالَ رَسُولُ اللَّهِ ﷺ: (أَمَا وَاللَّهِ لَأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ) فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: \"مَا كانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كانُوا أُولِي قُرْبى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحابُ الْجَحِيمِ\" وَأَنْزَلَ اللَّهُ فِي أَبِي طَالِبٍ فَقَالَ لِرَسُولِ اللَّهِ ﷺ: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلكِنَّ اللَّهَ يَهْدِي مَنْ يَشاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ﴾ [القصص: ٥٦].","en":"The Messenger of Allah ﷺ said: \"By Allah, I will seek forgiveness for you as long as I am not forbidden from it.\" Then Allah revealed: \"It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they be close relatives, after it has become clear to them that they are companions of Hellfire.\" And Allah revealed about Abu Talib, saying to the Messenger of Allah ﷺ: \"Indeed, you do not guide whom you love, but Allah guides whom He wills, and He is most knowing of the guided.\" [al-Qasas: 56]"}},{"id":"a_qasas","ch":"asbab","t":"إنك لا تهدي من أحببت","ay":[[28,56]],"h":[{"b":"muslim","n":"25","x":"قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ \" . فَأَبَى فَأَنْزَلَ اللَّهُ { إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ\"}","gr":"صحيح: رواه مسلم"}],"f":"عرض النبي ﷺ الشهادة على عمه أبي طالب عند الموت فأبى، فأنزل الله أن الهداية بيد الله وحده.","en_h":"The Prophet ﷺ said to his uncle at his death: \"Say: There is no god but Allah; I will testify for you with it on the Day of Resurrection.\" He refused. So Allah revealed: Indeed, you do not guide whom you love, but Allah guides whom He wills.","q":{"w":"ابن كثير","bk":"ibnkathir","s":28,"ay":56,"x":"وَقَدْ ثَبَتَ فِي الصَّحِيحَيْنِ أَنَّهَا نَزَلَتْ فِي أَبِي طَالِبٍ عَمّ رَسُولِ اللَّهِ ﷺ، وَقَدْ كَانَ يَحوطُه وَيَنْصُرُهُ، وَيَقُومُ فِي صَفِّهِ وَيُحِبُّهُ حُبًّا [شَدِيدًا] طَبْعِيًّا لَا شَرْعِيًّا، فَلَمَّا حَضَرَتْهُ الْوَفَاةُ وَحَانَ أَجَلُهُ، دَعَاهُ رَسُولُ اللَّهِ ﷺ إِلَى الْإِيمَانِ وَالدُّخُولِ فِي الْإِسْلَامِ، فَسَبَقَ الْقَدَرُ فِيهِ، وَاخْتُطِفَ مِنْ يَدِهِ، فَاسْتَمَرَّ عَلَى مَا كَانَ عَلَيْهِ مِنَ الْكُفْرِ، وَلِلَّهِ الْحِكْمَةُ التَّامَّةُ","en":"It is established in the two Sahihs that it was revealed about Abu Talib, the uncle of the Messenger of Allah ﷺ, who used to protect and support him, stand on his side and love him with a deep natural, not religious, love; when death came to him and his time was near, the Messenger of Allah ﷺ called him to faith and entering Islam, but the decree preceded it for him and he was snatched from his hand, so he remained in the disbelief he had; and to Allah belongs the perfect wisdom."}},{"id":"a_maida","ch":"asbab","t":"اليوم أكملت لكم دينكم","ay":[[5,3]],"h":[{"b":"bukhari","n":"45","x":"مِنَ الْيَهُودِ قَالَ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ، آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا لَوْ عَلَيْنَا مَعْشَرَ الْيَهُودِ نَزَلَتْ لاَتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا. قَالَ أَىُّ آيَةٍ قَالَ {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلاَمَ دِينًا}. قَالَ عُمَرُ قَدْ عَرَفْنَا ذَلِكَ الْيَوْمَ وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ قَائِمٌ بِعَرَفَةَ يَوْمَ جُمُعَةٍ","gr":"صحيح: رواه البخاري"}],"f":"سأل يهودي عمرَ عن آية في القرآن لو نزلت عليهم لاتخذوا يومها عيداً، فبيّن عمر أنها نزلت بعرفة يوم الجمعة.","en_h":"A Jew said to Umar: \"O Commander of the Faithful, a verse in your Book, if it had been revealed to us Jews we would have made that day a festival.\" He said: \"Which verse?\" He said: This day I have perfected for you your religion. Umar said: \"We know the day and the place where it was revealed to the Prophet ﷺ: he was standing at Arafa on a Friday.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":5,"ay":3,"x":"وَقَالَ أَسْبَاطٌ عَنِ السُّدِّيِّ: نَزَلَتْ هَذِهِ الْآيَةُ يَوْمَ عَرَفَة، فَلَمْ يُنَزَّلْ بَعْدَهَا حَلَالٌ وَلَا حَرَامٌ، وَرَجَعَ رَسُولُ اللَّهِ ﷺ فَمَاتَ.","en":"Asbat narrated from al-Suddi: \"This verse was revealed on the day of Arafa, and no lawful or unlawful matter was revealed after it, and the Messenger of Allah ﷺ went back and died.\""}},{"id":"a_safa","ch":"asbab","t":"إن الصفا والمروة من شعائر الله","ay":[[2,158]],"h":[{"b":"bukhari","n":"1643","x":"كَانُوا يَطُوفُونَ كُلُّهُمْ بِالصَّفَا وَالْمَرْوَةِ، فَلَمَّا ذَكَرَ اللَّهُ تَعَالَى الطَّوَافَ بِالْبَيْتِ، وَلَمْ يَذْكُرِ الصَّفَا وَالْمَرْوَةَ فِي الْقُرْآنِ قَالُوا يَا رَسُولَ اللَّهِ كُنَّا نَطُوفُ بِالصَّفَا وَالْمَرْوَةِ، وَإِنَّ اللَّهَ أَنْزَلَ الطَّوَافَ بِالْبَيْتِ، فَلَمْ يَذْكُرِ الصَّفَا فَهَلْ عَلَيْنَا مِنْ حَرَجٍ أَنْ نَطَّوَّفَ بِالصَّفَا وَالْمَرْوَةِ فَأَنْزَلَ اللَّهُ تَعَالَى {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} الآيَةَ. قَالَ أَبُو بَكْرٍ فَأَسْمَعُ هَذِهِ الآيَةَ نَزَلَتْ فِي الْفَرِيقَيْنِ كِلَيْهِمَا فِي الَّذِينَ كَانُوا يَتَحَرَّجُونَ أَنْ يَطُوفُوا بِالْجَاهِلِيَّةِ بِالصَّفَا وَالْمَرْوَةِ، وَالَّذِينَ يَطُوفُونَ ثُمَّ تَحَرَّجُوا أَنْ يَطُوفُوا بِهِمَا فِي الإِسْلاَمِ مِنْ أَجْلِ أَنَّ اللَّهَ تَعَالَى أَمَرَ بِالطَّوَافِ بِالْبَيْتِ","gr":"صحيح: رواه البخاري"}],"f":"بيّنت رواية الباب أن الآية نزلت لرفع الحرج الذي وجده الأنصار وغيرهم في الطواف بين الصفا والمروة.","en_h":"They used to circumambulate al-Safa and al-Marwa, and when Allah mentioned circumambulating the House without mentioning al-Safa they asked: \"O Messenger of Allah, we used to walk between al-Safa and al-Marwa; is there any blame on us?\" So Allah revealed: Indeed al-Safa and al-Marwa are among the signs of Allah.","q":{"w":"القرطبي","bk":"qurtubi","s":2,"ay":158,"x":"فِيهِ تِسْعُ مَسَائِلَ: الْأُولَى- رَوَى الْبُخَارِيُّ عَنْ عَاصِمِ بْنِ سُلَيْمَانَ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنْ الصَّفَا وَالْمَرْوَةِ فَقَالَ: كُنَّا نَرَى أَنَّهُمَا مِنْ أَمْرِ الْجَاهِلِيَّةِ، فَلَمَّا كَانَ الْإِسْلَامُ أَمْسَكْنَا عَنْهُمَا، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: \"إِنَّ الصَّفا وَالْمَرْوَةَ مِنْ شَعائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلا جُناحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِما\".","en":"First: al-Bukhari narrated from Asim ibn Sulayman who said: \"I asked Anas ibn Malik about al-Safa and al-Marwa, and he said: We thought they were from the matter of the Jahiliyya, so when Islam came we held back from them; then Allah revealed: Indeed al-Safa and al-Marwa are among the signs of Allah; so whoever performs Hajj of the House or Umra, there is no blame on him to walk between them.\""}},{"id":"a_siyam","ch":"asbab","t":"الخيط الأبيض من الخيط الأسود","ay":[[2,187]],"h":[{"b":"bukhari","n":"1916","x":"لَمَّا نَزَلَتْ {حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ} عَمَدْتُ إِلَى عِقَالٍ أَسْوَدَ وَإِلَى عِقَالٍ أَبْيَضَ، فَجَعَلْتُهُمَا تَحْتَ وِسَادَتِي، فَجَعَلْتُ أَنْظُرُ فِي اللَّيْلِ، فَلاَ يَسْتَبِينُ لِي، فَغَدَوْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَذَكَرْتُ لَهُ ذَلِكَ فَقَالَ \" إِنَّمَا ذَلِكَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ\"","gr":"صحيح: رواه البخاري"}],"f":"فهم عدي بن حاتم الآية على ظاهرها فبيّن له النبي ﷺ أن المراد سواد الليل وبياض النهار.","en_h":"Adi ibn Hatim said: \"When the verse, until the white thread becomes distinct from the black thread, was revealed, I took a black cord and a white cord and put them under my pillow and looked at them at night but could not distinguish them. In the morning I went to the Messenger of Allah ﷺ and told him, and he said: That is only the blackness of night and the whiteness of day.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":2,"ay":187,"x":"لَا بَلْ هُوَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ","en":"\"No, it is the blackness of the night and the whiteness of the day.\""}},{"id":"a_anam","ch":"asbab","t":"قل هو القادر على أن يبعث عليكم عذاباً","ay":[[6,65]],"h":[{"b":"bukhari","n":"7313","x":"قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ} قَالَ \" أَعُوذُ بِوَجْهِكَ \". {أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ} قَالَ \" أَعُوذُ بِوَجْهِكَ \". فَلَمَّا نَزَلَتْ {أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ} قَالَ \" هَاتَانِ أَهْوَنُ أَوْ أَيْسَرُ\"","gr":"صحيح: رواه البخاري"}],"f":"استعاذ النبي ﷺ بوجه الله عند نزول أوائل الآية، ولما نزل «أو يلبسكم شيعاً» قال «هاتان أهون أو أيسر».","en_h":"Jabir said: \"When the verse, Say: He is able to send punishment upon you from above you, was revealed, the Prophet ﷺ said: I seek refuge in Your Face. Or from beneath your feet: I seek refuge in Your Face. When Or to confuse you into factions was revealed he said: These two are lighter, or easier.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":6,"ay":65,"x":"لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: ﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ﴾ قَالَ رَسُولُ اللَّهِ ﷺ: \"أَعُوذُ بِوَجْهِكَ","en":"\"When this verse was revealed: Say: He is able to send punishment upon you from above you, the Messenger of Allah ﷺ said: I seek refuge in Your Face.\""}},{"id":"d_hasana","ch":"dua","t":"ربنا آتنا في الدنيا حسنة","ay":[[2,201]],"h":[{"b":"bukhari","n":"6389","x":"كَانَ أَكْثَرُ دُعَاءِ النَّبِيِّ صلى الله عليه وسلم \" اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ\"","gr":"صحيح: رواه البخاري"}],"f":"كان أكثر دعاء النبي ﷺ دعاء الآية، وهو جامع لخير الدنيا والآخرة.","en_h":"Anas said: \"The most frequent supplication of the Prophet ﷺ was: O Allah, our Lord, give us good in this world and good in the Hereafter and protect us from the punishment of the Fire.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":2,"ay":201,"x":"عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ ﷺ يَقُولُ: \"اللَّهم ربَّنا، آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","en":"From Anas ibn Malik, who said: the Prophet ﷺ used to say: \"O Allah, our Lord, give us good in this world and good in the Hereafter and protect us from the punishment of the Fire.\""}},{"id":"d_tafakkur","ch":"dua","t":"الآيات العشر من آل عمران عند القيام بالليل","ay":[[3,190,191]],"h":[{"b":"bukhari","n":"4569","x":"فَلَمَّا كَانَ ثُلُثُ اللَّيْلِ الآخِرُ قَعَدَ فَنَظَرَ إِلَى السَّمَاءِ فَقَالَ {إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلاَفِ ��للَّيْلِ وَالنَّهَارِ لآيَاتٍ لأُولِي الأَلْبَابِ}","gr":"صحيح: رواه البخاري"}],"f":"كان النبي ﷺ إذا قام في الثلث الأخير من الليل نظر إلى السماء وتلا الآية، ثم توضأ وصلى.","en_h":"Ibn Abbas said: \"I spent the night at my aunt Maymuna's. In the last third of the night the Prophet ﷺ sat up, looked at the sky and said: Indeed, in the creation of the heavens and the earth and the alternation of night and day are signs for those of understanding. Then he stood, performed ablution, brushed his teeth and prayed eleven rak'ahs.\"","q":{"w":"القرطبي","bk":"qurtubi","s":3,"ay":190,"x":"فَقَالَ: (يَا بِلَالُ، أَفَلَا أَكُونُ عَبْدًا شَكُورًا وَلَقَدْ أَنْزَلَ اللَّهُ عَلَيَّ اللَّيْلَةَ آيَةً \"إِنَّ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهارِ لَآياتٍ لِأُولِي الْأَلْبابِ\"- ثُمَّ قَالَ: وَيْلٌ لِمَنْ قَرَأَهَا وَلَمْ يَتَفَكَّرْ فِيهَا.","en":"He said: \"O Bilal, should I not be a thankful servant, when Allah has revealed to me tonight a verse: Indeed, in the creation of the heavens and the earth and the alternation of night and day are signs for those of understanding?\" Then he said: \"Woe to whoever recites it and does not reflect on it.\""}},{"id":"d_ummati","ch":"dua","t":"قول إبراهيم وعيسى: اللهم أمتي","ay":[[14,36],[5,118]],"h":[{"b":"muslim","n":"202","x":"تَلاَ قَوْلَ اللَّهِ عَزَّ وَجَلَّ فِي إِبْرَاهِيمَ { رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي} الآيَةَ . وَقَالَ عِيسَى عَلَيْهِ السَّلاَمُ { إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ} فَرَفَعَ يَدَيْهِ وَقَالَ \" اللَّهُمَّ أُمَّتِي أُمَّتِي \" . وَبَكَى فَقَالَ اللَّهُ عَزَّ وَجَلَّ يَا جِبْرِيلُ اذْهَبْ إِلَى مُحَمَّدٍ وَرَبُّكَ أَعْلَمُ فَسَلْهُ مَا يُبْكِيكَ فَأَتَاهُ جِبْرِيلُ - عَلَيْهِ الصَّلاَةُ وَالسَّلاَمُ - فَسَأَلَهُ فَأَخْبَرَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم بِمَا قَالَ . وَهُوَ أَعْلَمُ . فَقَالَ اللَّهُ يَا جِبْرِيلُ اذْهَبْ إِلَى مُحَمَّدٍ فَقُلْ إِنَّا سَنُرْضِيكَ فِي أُمَّتِكَ وَلاَ نَسُوءُكَ","gr":"صحيح: رواه مسلم"}],"f":"تلا النبي ﷺ قول إبراهيم وعيسى عليهما السلام فرفع يديه وبكى داعياً لأمته، فبشّره الله بأنه سيرضيه فيهم.","en_h":"The Prophet ﷺ recited the words of Ibrahim, \"My Lord, they have led astray many of the people\", and the words of Isa, \"If You punish them, they are Your servants; and if You forgive them, You are the Mighty, the Wise.\" He raised his hands and said: \"O Allah, my community, my community!\" and wept. Allah said: \"O Jibril, go to Muhammad and ask him why he weeps.\" Then Allah said: \"Go to Muhammad and say: We will please you regarding your community and will not displease you.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":14,"ay":36,"x":"أَنَّ رَسُولَ اللَّهِ ﷺ تَلَا قَوْلَ إِبْرَاهِيمَ: ﴿رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾ وَقَوْلَ عِيسَى عَلَيْهِ السَّلَامُ: ﴿إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ﴾ وَرَفْعَ يَدَيْهِ، [ثُمَّ] قَالَ: \"اللَّهُمَّ أُمَّتِي، اللَّهُمَّ أُمَّتِي، اللَّهُمَّ أُمَّتِي\"، وَبَكَى","en":"The Messenger of Allah ﷺ recited the words of Ibrahim: \"My Lord, they have led astray many of the people; so whoever follows me, he is of me, and whoever disobeys me, indeed You are Forgiving and Merciful\", and the words of Isa, peace be upon him: \"If You punish them, they are Your servants, and if You forgive them, You are the Mighty, the Wise\", and raised his hands and said: \"O Allah, my community, O Allah, my community, O Allah, my community,\" and wept."}},{"id":"d_nasr","ch":"dua","t":"سورة النصر والتسبيح بحمد الله","ay":[[110,1,3]],"h":[{"b":"bukhari","n":"4968","x":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ \" سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي \". يَتَأَوَّلُ الْقُرْآنَ","gr":"صحيح: رواه البخاري"}],"f":"بيّنت عائشة رضي الله عنها أن النبي ﷺ كان يتأول «فسبّح بحمد ربك واستغفره» فيكثر من التسبيح والاستغفار.","en_h":"Aisha said: \"The Messenger of Allah ﷺ used to say frequently in his bowing and prostration: Glory be to You, O Allah, our Lord, and praise be to You; O Allah, forgive me, interpreting the Quran.\"","q":{"w":"ابن كثير","bk":"ibnkathir","s":110,"ay":1,"x":"كَانَ رَسُولُ اللَّهِ ﷺ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: \"سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي\" يَتَأَوَّلُ الْقُرْآنَ","en":"\"The Messenger of Allah ﷺ used to say frequently in his bowing and prostration: Glory be to You, O Allah our Lord, and praise be to You; O Allah, forgive me,\" interpreting the Quran."}}],"ay":{"0":"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","1":"ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","2":"ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","3":"مَٰلِكِ يَوۡمِ ٱلدِّينِ","4":"إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ","5":"ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ","6":"صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ","7":"الٓمٓ","8":"ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ","9":"ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","10":"وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ","11":"أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","149":"وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ","164":"۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ","193":"أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ","207":"وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ","244":"حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ","261":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ","291":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ","292":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","299":"هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ","323":"قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","482":"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ","483":"ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","551":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا","557":"فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا","572":"مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا","671":"حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","786":"إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","853":"قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ","870":"ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ","1219":"وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ","1347":"مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ","1389":"۞ لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ","1574":"وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ","1773":"أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ","1774":"تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ","1776":"يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ","1785":"رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ","1888":"وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ","1944":"بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ","2107":"وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا","2140":"ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ","2141":"قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا","2142":"مَّٰكِثِينَ فِيهِ أَبَدٗا","2143":"وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗا","2144":"مَّا لَهُم بِهِۦ مِنۡ عِلۡمٖ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبٗا","2145":"فَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا","2146":"إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا","2586":"يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ","2853":"لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ","3145":"وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ","3146":"وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ","3147":"فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ","3307":"إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","3519":"فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ","3538":"ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا","3553":"لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا","4192":"وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ","4566":"فَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ","4567":"أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ","4583":"إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا","4584":"لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا","4585":"وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا","4786":"وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ","4787":"إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ","4796":"وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ","4797":"عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ","4798":"عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ","4799":"إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ","4800":"مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ","4801":"لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ","5005":"وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ","5006":"فِي سِدۡرٖ مَّخۡضُودٖ","5007":"وَطَلۡحٖ مَّنضُودٖ","5008":"وَظِلّٖ مَّمۡدُودٖ","5132":"مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","5241":"تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","5242":"ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ","5243":"ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ","5244":"ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ","5245":"وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ","5851":"أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","5852":"لِيَوۡمٍ عَظِيمٖ","5853":"يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","5890":"فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ","5891":"فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا","6204":"إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ","6205":"فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ","6206":"إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ","6213":"إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ","6214":"وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا","6215":"فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا","6216":"تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ","6217":"مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ","6218":"سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ","6221":"قُلۡ هُوَ ٱللَّهُ أَحَدٌ","6222":"ٱللَّهُ ٱلصَّمَدُ","6223":"لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ","6224":"وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ","6225":"قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ","6226":"مِن شَرِّ مَا خَلَقَ","6227":"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","6228":"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ","6229":"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","6230":"قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ","6231":"مَلِكِ ٱلنَّاسِ","6232":"إِلَٰهِ ٱلنَّاسِ","6233":"مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ","6234":"ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ","6235":"مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ"},"nay":120,"nh":51};
